function validProposals(value: unknown): value is SceneProposal[] {
  return (
    Array.isArray(value) &&
    value.length <= 12 &&
    value.every(
      (p) =>
        p &&
        typeof p === "object" &&
        p.origin === "writer" &&
        typeof p.text === "string" &&
        p.text.trim().length > 0 &&
        p.text.length <= 600 &&
        SCENE_DIMENSIONS.some(({ id }) => id === p.dimension),
    )
