input.content:
"use node";

/**
 * Scene Bench pictures on Twyne's hosted models.
 *
 * Every call spends the writer's Not Organic credit, so the bench only calls
 * these after the writer has switched generation on in Settings and pressed
 * Generate. There is no monthly picture cap: the wallet balance is the limit,
 * and the gateway refuses a request the balance cannot cover. Each request
 * carries its own cost ceiling so one picture can never spend more than the
 * price the bench showed.
 */

import { action, type ActionCtx } from "./_generated/server";
import { makeFunctionReference } from "convex/server";
import { v } from "convex/values";
import { generateImage, generateText } from "ai";
import { createOpenAI } from "@ai-sdk/openai";
import {
  issueNotOrganicAccessToken,
  notOrganicIssuer,
  notOrganicOpenAiRoute,
  providerJsonRequest,
  type NotOrganicModelAlias,
} from "./lib/notorganic";
import { consumeRateLimit, RATE_LIMITS } from "./lib/rateLimit";
import { liveVoiceAccess } from "../src/utils/live-voice-contract";
import {
  SCENE_PICTURE_BUDGET_MICROS,
  SCENE_READING_BUDGET_MICROS,
} from "../src/utils/scene-media-credit";
import { SCENE_READING_SYSTEM } from "../src/utils/scene-bench";
import { createAiTraceId } from "../src/utils/ai-deterministic-evals";
import {
  utcDayFromTimestamp,
  type UsageEvent,
} from "../src/utils/usage-domain";

const linkRef = makeFunctionReference<
  "query",
  { productSubject: string },
  { did: string; sessionVersion: number } | null
>("providerIdentity:getLinkedDidBySubject");

const recordTrustedUsage = makeFunctionReference<
  "mutation",
  { ownerId: string; event: UsageEvent },
  { inserted: boolean }
>("usage:recordTrustedEvent");

/** Image endpoints reject long prompts; the bench trims the excerpt first. */
const MAX_PICTURE_PROMPT_CHARS = 6_000;
const MAX_READING_PROMPT_CHARS = 16_000;
/** A generated picture is a few MB at most; base64 adds a third. */
const MAX_READING_IMAGE_BASE64 = 8 * 1024 * 1024;

async function account(ctx: ActionCtx) {
  const identity = await ctx.auth.getUserIdentity();
  if (!identity) throw new Error("Sign in to generate scene pictures.");
  const link = await ctx.runQuery(linkRef, {
    productSubject: identity.subject || identity.tokenIdentifier,
  });
  if (!link)
    throw new Error("Link your Not Organic account to use hosted pictures.");
  return { ...link, identity };
}

/** Pro and welcome credit both spend from the same wallet balance. */
async function walletCredit(
  link: { did: string; sessionVersion: number },
  feature: string,
) {
  const token = await issueNotOrganicAccessToken({
    ...link,
    feature,
    capabilities: ["wallet:read"],
  });
  const wallet = await providerJsonRequest<unknown>(
    "/v1/wallet",
    token,
    {},
    { issuer: notOrganicIssuer(), feature },
  );
  return liveVoiceAccess(wallet);
}

async function hostedRoute(
  link: { did: string; sessionVersion: number },
  alias: NotOrganicModelAlias,
  feature: string,
  maxCostMicrousd: number,
) {
  const token = await issueNotOrganicAccessToken({
    ...link,
    feature,
    capabilities: [`infer:${alias}`],
  });
  const route = notOrganicOpenAiRoute(
    token,
    alias,
    feature,
    notOrganicIssuer(),
    fetch,
    { maxCostMicrousd },
  );
  return {
    route,
    provider: createOpenAI({
      baseURL: route.baseURL,
      apiKey: route.apiKey,
      headers: route.headers,
      fetch: route.fetch,
    }),
  };
}

/** The wallet is authoritative for price; this keeps the attempt in My Desk. */
async function recordAttempt(
  ctx: ActionCtx,
  ownerId: string,
  feature: "scene-image" | "scene-reading",
  model: string,
  outcome: "completed" | "failed",
  usage: { inputTokens?: number; outputTokens?: number } = {},
) {
  const occurredAt = Date.now();
  const traceId = createAiTraceId(feature);
  try {
    await ctx.runMutation(recordTrustedUsage, {
      ownerId,
      event: {
        eventKey: `${traceId}:1:notorganic:${model}`,
        occurredAt,
        day: utcDayFromTimestamp(occurredAt),
        source: "hosted",
        authority: "server",
        feature,
        provider: "notorganic",
        model,
        editorialActionId: traceId,
        traceId,
        attempt: 1,
        outcome,
        ...Object.fromEntries(
          Object.entries(usage).filter(
            ([, value]) => Number.isSafeInteger(value) && (value as number) >= 0,
          ),
        ),
        costKind: "unknown",
      },
    });
  } catch {
    // Usage history must never fail the picture the writer already paid for.
  }
}

/** Balance and price for the bench to show before the writer opts in. */
export const access = action({
  args: {},
  returns: v.object({
    eligible: v.boolean(),
    availableMicros: v.number(),
    pictureBudgetMicros: v.number(),
    readingBudgetMicros: v.number(),
  }),
  handler: async (ctx) => {
    const link = await account(ctx);
    const { eligible, availableMicros } = await walletCredit(
      link,
      "scene-image",
    );
    return {
      eligible,
      availableMicros,
      pictureBudgetMicros: SCENE_PICTURE_BUDGET_MICROS,
      readingBudgetMicros: SCENE_READING_BUDGET_MICROS,
    };
  },
});

export const picture = action({
  args: { prompt: v.string() },
  returns: v.object({
    base64: v.string(),
    mediaType: v.string(),
    model: v.string(),
  }),
  handler: async (ctx, args) => {
    const prompt = args.prompt.trim();
    if (!prompt) throw new Error("Select a scene before generating a picture.");
    if (prompt.length > MAX_PICTURE_PROMPT_CHARS)
      throw new Error("That passage is too long to picture. Select less text.");
    const link = await account(ctx);
    await consumeRateLimit(ctx, {
      action: "scene:picture",
      identifier: link.identity.tokenIdentifier,
      ...RATE_LIMITS.scenePicture,
    });
    const { eligible, availableMicros } = await walletCredit(
      link,
      "scene-image",
    );
    if (!eligible)
      throw new Error(
        "Hosted pictures need Pro or welcome credit. You can use your own image model in Settings instead.",
      );
    if (availableMicros < SCENE_PICTURE_BUDGET_MICROS)
      throw new Error(
        "Your credit has run out for this month. Add credit, or use your own image model in Settings.",
      );
    const { route, provider } = await hostedRoute(
      link,
      "image",
      "scene-image",
      SCENE_PICTURE_BUDGET_MICROS,
    );
    try {
      const { image } = await generateImage({
        model: provider.image(route.model),
        prompt,
        n: 1,
        maxRetries: 0,
        abortSignal: AbortSignal.timeout(120_000),
      });
      await recordAttempt(
        ctx,
        link.identity.tokenIdentifier,
        "scene-image",
        route.model,
        "completed",
      );
      return {
        base64: image.base64,
        mediaType: image.mediaType || "image/png",
        model: route.model,
      };
    } catch (error) {
      await recordAttempt(
        ctx,
        link.identity.tokenIdentifier,
        "scene-image",
        route.model,
        "failed",
      );
      throw error;
    }
  },
});

/** Shows the picture to a vision model and returns its raw JSON answer. */
export const reading = action({
  args: {
    prompt: v.string(),
    imageBase64: v.string(),
    mediaType: v.string(),
  },
  returns: v.object({ text: v.string() }),
  handler: async (ctx, args) => {
    if (args.prompt.length > MAX_READING_PROMPT_CHARS)
      throw new Error("That passage is too long to compare.");
    if (
      !args.imageBase64 ||
      args.imageBase64.length > MAX_READING_IMAGE_BASE64
    )
      throw new Error("That picture cannot be compared.");
    if (!/^image\/(png|jpeg|webp|gif)$/.test(args.mediaType))
      throw new Error("Unsupported picture type.");
    const link = await account(ctx);
    await consumeRateLimit(ctx, {
      action: "scene:reading",
      identifier: link.identity.tokenIdentifier,
      ...RATE_LIMITS.scenePicture,
    });
    const { route, provider } = await hostedRoute(
      link,
      "vision",
      "scene-reading",
      SCENE_READING_BUDGET_MICROS,
    );
    try {
      const result = await generateText({
        model: provider.chat(route.model),
        system: SCENE_READING_SYSTEM,
        messages: [
          {
            role: "user",
            content: [
              { type: "text", text: args.prompt },
              {
                type: "image",
                image: args.imageBase64,
                mediaType: args.mediaType,
              },
            ],
          },
        ],
        temperature: 0.2,
        maxRetries: 0,
        abortSignal: AbortSignal.timeout(60_000),
      });
      await recordAttempt(
        ctx,
        link.identity.tokenIdentifier,
        "scene-reading",
        route.model,
        "completed",
        {
          inputTokens: result.usage.inputTokens,
          outputTokens: result.usage.outputTokens,
        },
      );
      return { text: result.text };
    } catch (error) {
      await recordAttempt(
        ctx,
        link.identity.tokenIdentifier,
        "scene-reading",
        route.model,
        "failed",
      );
      throw error;
    }
  },
});

/**
 * Credit language shared by Scene Bench, its hosted actions, and Settings.
 *
 * Twyne does not cap how many pictures a writer makes. It warns: once,
 * plainly, that pictures spend credit quickly, and again whenever the wallet
 * is running low.
 */

/** Ceiling sent with each hosted picture; the gateway never charges more. */
export const SCENE_PICTURE_BUDGET_MICROS = 250_000;
/** Ceiling for the vision pass that compares a picture with its passage. */
export const SCENE_READING_BUDGET_MICROS = 50_000;
/** Below this the bench warns that credit is about to run out. */
export const LOW_CREDIT_MICROS = 1_000_000;

export const SCENE_CREDIT_WARNING =
  "Pictures cost far more than text. A few dozen can use up a month's included credit.";

export function formatCreditMicros(micros: number): string {
  const usd = Math.max(0, micros) / 1_000_000;
  return `$${usd < 10 ? usd.toFixed(2) : usd.toFixed(0)}`;
}

/** The general low-balance warning, or null when there is room to spare. */
export function lowCreditWarning(availableMicros: number): string | null {
  if (availableMicros < SCENE_PICTURE_BUDGET_MICROS)
    return "Your credit has run out for this month. Add credit or use your own model to keep generating.";
  if (availableMicros < LOW_CREDIT_MICROS)
    return `Your credit is running low: ${formatCreditMicros(availableMicros)} left this month.`;
  return null;
}

/** What one picture plus its comparison can cost on Twyne's models. */
export function hostedSceneCostLabel(): string {
  return `Up to ${formatCreditMicros(
    SCENE_PICTURE_BUDGET_MICROS + SCENE_READING_BUDGET_MICROS,
  )} a picture from your credit`;
}

/**
 * Scene Bench pictures: route one request to Twyne's hosted image model or to
 * the writer's own provider, then compare the picture with the passage.
 *
 * Nothing here runs unless the writer has switched generation on and pressed
 * Generate. The bench owns that consent; this module only does the work.
 */
import type { ConvexClient } from "convex/browser";
import { makeFunctionReference } from "convex/server";
import type { AiSettings, SceneMediaSettings } from "../types";
import { resolveFeatureConfig } from "./ai-client";
import {
  createSceneInventory,
  createScenePicturePrompt,
  createSceneReadingPrompt,
  parseSceneReading,
  SCENE_READING_SYSTEM,
  type ScenePassage,
  type ScenePicture,
  type ScenePictureMode,
  type SceneProposal,
} from "./scene-bench";
import { hostedSceneCostLabel } from "./scene-media-credit";

const hostedAccess = makeFunctionReference<
  "action",
  Record<string, never>,
  { eligible: boolean; availableMicros: number }
>("sceneMedia:access");
const hostedPicture = makeFunctionReference<
  "action",
  { prompt: string },
  { base64: string; mediaType: string; model: string }
>("sceneMedia:picture");
const hostedReading = makeFunctionReference<
  "action",
  { prompt: string; imageBase64: string; mediaType: string },
  { text: string }
>("sceneMedia:reading");

export const DEFAULT_SCENE_MEDIA: SceneMediaSettings = {
  enabled: false,
  source: "twyne",
};

export function sceneMediaSettings(settings: AiSettings): SceneMediaSettings {
  return { ...DEFAULT_SCENE_MEDIA, ...settings.sceneMedia };
}

export interface ScenePictureCapability {
  available: boolean;
  /** Generation is off until the writer turns it on in Settings. */
  enabled: boolean;
  source: SceneMediaSettings["source"];
  destination: string;
  costLabel: string;
  unavailableReason?: string;
  /** Hosted only: the wallet balance the bench warns against. */
  availableMicros?: number;
}

/** Describe where a picture would go and what it costs, without sending one. */
export async function describeScenePictures(
  settings: AiSettings,
  options: { client: ConvexClient | null; signedIn: boolean },
): Promise<ScenePictureCapability> {
  const media = sceneMediaSettings(settings);
  const base = { enabled: media.enabled, source: media.source };
  if (media.source === "provider") {
    const image = resolveFeatureConfig(settings, "scene-image");
    const reader = resolveFeatureConfig(settings, "scene-reading");
    return image
      ? {
          ...base,
          available: true,
          destination: `${image.provider.name} · ${image.model}${
            reader ? `, compared by ${reader.model}` : ""
          }`,
          costLabel: "Charged by your provider at its image price.",
        }
      : {
          ...base,
          available: false,
          destination: "Your image model",
          costLabel: "Charged by your provider.",
          unavailableReason:
            "Add an OpenAI, Google, OpenRouter, or OpenAI-compatible provider in Settings and choose it for Scene Pictures.",
        };
  }
  const hosted = {
    ...base,
    destination: "Twyne's image model",
    costLabel: hostedSceneCostLabel(),
  };
  if (!options.signedIn || !options.client)
    return {
      ...hosted,
      available: false,
      unavailableReason: "Sign in to use Twyne's image model.",
    };
  if (!media.enabled) return { ...hosted, available: true };
  try {
    const access = await options.client.action(hostedAccess, {});
    return access.eligible
      ? { ...hosted, available: true, availableMicros: access.availableMicros }
      : {
          ...hosted,
          available: false,
          availableMicros: access.availableMicros,
          unavailableReason:
            "Twyne's image model needs Pro or welcome credit. You can choose your own image model in Settings.",
        };
  } catch (error) {
    return {
      ...hosted,
      available: false,
      unavailableReason:
        error instanceof Error
          ? error.message
          : "Twyne's image model is unavailable.",
    };
  }
}

export interface ScenePictureRequest {
  passage: ScenePassage;
  mode: ScenePictureMode;
  proposals: readonly SceneProposal[];
  settings: AiSettings;
  client: ConvexClient | null;
  signal?: AbortSignal;
}

/** Draw the passage. The comparison follows separately so the picture shows first. */
export async function generateScenePicture(
  request: ScenePictureRequest,
): Promise<ScenePicture> {
  const inventory = createSceneInventory(request.passage);
  const prompt = createScenePicturePrompt(
    inventory,
    request.mode,
    request.proposals,
  );
  if (!prompt) throw new Error("Select a scene before generating a picture.");
  const media = sceneMediaSettings(request.settings);
  if (!media.enabled)
    throw new Error("Turn on Scene Pictures in Settings to generate.");
  let image: { base64: string; mediaType: string };
  let destination: string;
  let model: string;
  if (media.source === "provider") {
    const { runClientScenePicture } = await import("./ai-client");
    const result = await runClientScenePicture(
      prompt,
      request.settings,
      request.signal,
    );
    if (!result)
      throw new Error("Choose an image-capable provider in Settings first.");
    image = result;
    destination = result.provider;
    model = result.model;
  } else {
    if (!request.client) throw new Error("Sign in to generate pictures.");
    const result = await request.client.action(hostedPicture, { prompt });
    image = result;
    destination = "Twyne";
    model = result.model;
  }
  return {
    passage: { ...request.passage },
    mode: request.mode,
    mediaType: image.mediaType,
    base64: image.base64,
    destination,
    model,
    createdAt: Date.now(),
    reading: null,
  };
}

/** What the picture took from the page, what it invented, what it got wrong. */
export async function readScenePicture(
  picture: ScenePicture,
  settings: AiSettings,
  client: ConvexClient | null,
  signal?: AbortSignal,
): Promise<ScenePicture["reading"]> {
  const prompt = createSceneReadingPrompt(
    createSceneInventory(picture.passage),
    picture.mode,
  );
  if (!prompt) return null;
  const image = { base64: picture.base64, mediaType: picture.mediaType };
  let raw: string | null;
  if (sceneMediaSettings(settings).source === "provider") {
    const { runClientSceneReading } = await import("./ai-client");
    raw = await runClientSceneReading(
      { system: SCENE_READING_SYSTEM, prompt, image },
      settings,
      signal,
    );
  } else {
    if (!client) return null;
    raw = (
      await client.action(hostedReading, {
        prompt,
        imageBase64: image.base64,
        mediaType: image.mediaType,
      })
    ).text;
  }
  return raw ? parseSceneReading(raw, picture.passage) : null;
}

result.output:
  ui.briefPassage &&
  sceneSnapshotMatches({ passage: ui.briefPassage }, props.passage);

return (
  <InstrumentMotion
    state={assessment ? "arrive" : "rest"}
    quiet={props.quiet}
    class="scene-bench"
  >
    <header class="scene-bench__head">
      <InstrumentArt kind="scene" size="compact" />
      <div>
        <h2>Scene bench</h2>
        <p>See what the passage gives you, then try an idea.</p>
      </div>
    </header>
    {current.status !== "ready" ? (
      <p class="scene-bench__notice">{current.reason}</p>
    ) : (
      <>
        <details class="scene-bench__source">
          <summary>
            Selected passage · {current.spans.length}{" "}
            {current.spans.length === 1 ? "sentence" : "sentences"}
          </summary>
          <blockquote>{props.passage.text}</blockquote>
        </details>
        <p class="scene-bench__method">
          Local English cue scan. A quoted cue is evidence to inspect; an
          unlisted detail may still be present.
        </p>
        <dl class="scene-bench__inventory">
          {SCENE_DIMENSIONS.map(({ id, label }) => {
            const model = assessment?.dimensions[id];
            const selected =
              model?.state === "selected"
                ? current.spans.find((span) => span.id === model.spanId)
                : null;
            const local = current.dimensions[id];
            const spans = selected
              ? [selected]
              : local
                  .slice(0, 2)
                  .flatMap((cue) =>
                    current.spans.filter((span) => span.id === cue.spanId),
                  );
            return (
              <div
                key={id}
                class="scene-bench__dimension"
                data-scene-dimension={id}
              >
                <dt>{label}</dt>
                <dd>
                  {spans.map((span) => (
                    <div class="scene-bench__evidence" key={span.id}>
                      <blockquote>{span.text}</blockquote>
                      <div class="scene-bench__evidence-foot">
                        <span>
                          {selected
                            ? `${assessment!.model} selection`
                            : `Local cue: “${local.find((cue) => cue.spanId === span.id)?.cue ?? ""}”`}
                        </span>
                        {props.onLocate$ && (
                          <button
                            type="button"
                            onClick$={async () => {
                              if (sceneSpanMatches(span, props.passage))
                                await props.onLocate$?.(span, props.passage);
                            }}
                          >
                            Find in passage
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                  {!spans.length && (
                    <p class="scene-bench__unidentified">
                      No cue identified locally.
                    </p>
                  )}
                  {local.length > 2 && !selected && (
                    <p class="scene-bench__method">
                      Showing 2 of {local.length} local cues.
                    </p>
                  )}
                  {model?.state === "uncertain" && (
                    <p class="scene-bench__method">
                      The model reading was uncertain; local cues remain for
                      inspection.
                    </p>
                  )}
                  {model?.state === "not-identified" && (
                    <p class="scene-bench__method">
                      The model did not identify explicit evidence for this
                      dimension.
                    </p>
                  )}
                </dd>
              </div>
            );
          })}
        </dl>

        <details class="scene-bench__provider">
          <summary>Ask for a model reading</summary>
          <p>
            Selects evidence and reads the scene's pressure. It does not
            rewrite or add scene details.
          </p>
          <p class="scene-bench__method">
            {canRequest(props.judgement) && props.onJudge$
              ? `Sends this selected passage to ${props.judgement!.destination}. ${props.judgement!.costLabel}`
              : (props.judgement?.unavailableReason ??
                "No judgement provider is connected here. The local inventory remains available.")}
          </p>
          <button
            type="button"
            disabled={
              ui.busy || !canRequest(props.judgement) || !props.onJudge$
            }
            onClick$={async () => {
              if (!props.onJudge$ || !canRequest(props.judgement) || ui.busy)
                return;
              const snapshot = createSceneInventory(props.passage);
              const request = createSceneJudgementRequest(snapshot);
              if (!request) return;
              ui.busy = true;
              ui.error = "";
              try {
                const result = resolveSceneJudgement(
                  snapshot,
                  await props.onJudge$(request),
                  props.passage,
                );
                if (result.ok) ui.assessment = result.assessment;
                else
                  ui.error =
                    result.reason === "stale"
                      ? "The passage changed while the model read it. Ask again for this version."
                      : "The model did not return a usable reading. The local inventory is still available.";
              } catch {
                ui.error =
                  "The model reading is unavailable. The local inventory is still available.";
              } finally {
                ui.busy = false;
              }
            }}
          >
            {ui.busy ? "Reading the passage…" : "Read the scene with a model"}
          </button>
        </details>
        {ui.error && (
          <p class="scene-bench__notice" role="status">
            {ui.error}
          </p>
        )}
        {ui.assessment && !assessment && (
          <p class="scene-bench__notice">
            The previous model reading belongs to an earlier selection.
          </p>
        )}
        {assessment && (
          <InstrumentMotionPart part="result" class="scene-bench__reading">
            <InstrumentRule />
            <h3>
              {assessment.tension.uncertain
                ? "The scene pressure is uncertain"
                : SCENE_TENSION_LABELS[assessment.tension.choice]}
            </h3>
            <p class="scene-bench__method">
              {assessment.model} reading ·{" "}
              {Math.round(assessment.tension.probability * 100)}% probability
              for this interpretation. This is not a writing grade.
            </p>
          </InstrumentMotionPart>
        )}

        <section
          class="scene-bench__section"
          aria-label="Read the scene aloud"
        >
          <h3>Hear the passage</h3>
